const { chromium } = require\('./node_modules/playwright'\);
\(async \(\) => {
  const browser = await chromium.launch\(\);
  const page = await browser.newPage\({ viewport: { width: 1440, height: 900 } }\);

  // Monitor network requests for chunk files
  const chunkRequests = [];
  page.on\('requestfailed', req => {
    chunkRequests.push\('FAILED: ' + req.url\(\).substring\(req.url\(\).lastIndexOf\('/'\) + 1\)\);
  }\);

  await page.goto\('http://localhost:3000/invest', { waitUntil: 'networkidle', timeout: 30000 }\);
  await page.waitForTimeout\(3000\);

  // Scroll through to trigger all lazy loads
  for \(let y = 0; y < 22000; y += 600\) {
    await page.evaluate\(scrollY => window.scrollTo\(0, scrollY\), y\);
    await page.waitForTimeout\(100\);
  }
  await page.waitForTimeout\(3000\);

  if \(chunkRequests.length > 0\) {
    console.log\('Failed requests:'\);
    chunkRequests.forEach\(r => console.log\(' ', r\)\);
  } else {
    console.log\('No failed network requests'\);
  }

  // Try importing the component directly in the page context
  const result = await page.evaluate\(async \(\) => {
    try {
      const mod = await import\('/invest/_components/GlobalCoordinators'\);
      return { success: true, keys: Object.keys\(mod\) };
    } catch \(e\) {
      return { success: false, error: e.message };
    }
  }\);
  console.log\('Direct import:', JSON.stringify\(result\)\);

  // Check if maybe it rendered but is hidden
  const hidden = await page.evaluate\(\(\) => {
    const all = document.querySelectorAll\('*'\);
    for \(const el of all\) {
      const style = window.getComputedStyle\(el\);
      if \(el.textContent?.includes\('Global Reach'\) && \(style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0'\)\) {
        return { found: true, display: style.display, visibility: style.visibility, opacity: style.opacity };
      }
    }
    return { found: false };
  }\);
  console.log\('Hidden check:', JSON.stringify\(hidden\)\);

  await browser.close\(\);
}\)\(\);
